    "workspace_binding_version_id": {"type": "string", "pattern": "^workspace_binding_version:[a-f0-9]{32}$"},
    "operation_binding_ref": {"$ref": "#/definitions/ref"},
    "binding_kind": {"enum": ["lineage_template", "firing_view"]},
    "workspace_lineage_ref": {"$ref": "#/definitions/ref"},
    "base_revision_ref": {"$ref": "#/definitions/ref"},
    "template_binding_ref": {"$ref": "#/definitions/nullable_ref"},
    "invocation_ref": {"$ref": "#/definitions/nullable_ref"},
    "transition_firing_ref": {"$ref": "#/definitions/nullable_ref"},
    "allowed_root": {"type": "string", "minLength": 1},
    "allowed_prefixes": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
    "mode": {"const": "read_write"},
    "workspace_seed_manifest_ref": {"$ref": "#/definitions/nullable_resource_ref"},
    "workspace_runtime_ref": {"$ref": "#/definitions/nullable_resource_ref"}
  },
  "required": [
    "workspace_binding_id", "workspace_binding_version_id",
    "operation_binding_ref", "binding_kind", "workspace_lineage_ref",
    "base_revision_ref", "template_binding_ref", "invocation_ref",
    "transition_firing_ref", "allowed_root", "allowed_prefixes", "mode",
    "workspace_seed_manifest_ref", "workspace_runtime_ref"
  ],
  "allOf": [
    {
      "if": {"properties": {"binding_kind": {"const": "lineage_template"}}},
      "then": {
        "properties": {
          "template_binding_ref": {"type": "null"},
          "invocation_ref": {"type": "null"},
          "transition_firing_ref": {"type": "null"}
        }
      },
      "else": {
        "properties": {
          "template_binding_ref": {"$ref": "#/definitions/ref"},
          "invocation_ref": {"$ref": "#/definitions/ref"},
          "transition_firing_ref": {"$ref": "#/definitions/ref"}
        }
      }
    }
  ]
}

registry_v1/workspace_revision/v1.source:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "registry_v1/workspace_revision/v1",
  "title": "RPNH workspace lineage revision",
  "type": "object",
  "additionalProperties": false,
  "definitions": {
    "ref": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "entity_type": {"type": "string"},
        "logical_id": {"type": "string", "pattern": "^[a-z][a-z0-9_]*:[a-f0-9]{32}$"},
        "version_id": {"type": "string", "pattern": "^[a-z][a-z0-9_]*:[a-f0-9]{32}$"}
      },
      "required": ["entity_type", "logical_id", "version_id"]
    },
    "nullable_ref": {"oneOf": [{"$ref": "#/definitions/ref"}, {"type": "null"}]},
    "resource_ref": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "resource_id": {"type": "string", "pattern": "^resource:[a-f0-9]{32}$"},
        "resource_version_id": {"type": "string", "pattern": "^resource_version:[a-f0-9]{32}$"}
      },
      "required": ["resource_id", "resource_version_id"]
    },
    "nullable_resource_ref": {
      "oneOf": [{"$ref": "#/definitions/resource_ref"}, {"type": "null"}]
    },
    "nullable_summary": {
      "oneOf": [
        {"type": "string", "maxLength": 600},
        {"type": "null"}
      ]
    },
    "path_list": {
      "type": "array",
      "uniqueItems": true,
      "items": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"}
    },
    "path_delta": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"},
        "change_kind": {"enum": ["create", "update", "delete"]},
        "before_resource_ref": {"$ref": "#/definitions/nullable_resource_ref"},
        "after_resource_ref": {"$ref": "#/definitions/nullable_resource_ref"},
        "before_summary": {"$ref": "#/definitions/nullable_summary"},
        "after_summary": {"$ref": "#/definitions/nullable_summary"}
      },
      "required": [
        "path", "change_kind", "before_resource_ref", "after_resource_ref",
        "before_summary", "after_summary"
      ],
      "allOf": [
        {
          "if": {"properties": {"change_kind": {"const": "create"}}},
          "then": {
            "properties": {
              "before_resource_ref": {"type": "null"},
              "after_resource_ref": {"$ref": "#/definitions/resource_ref"},
              "before_summary": {"type": "null"},
              "after_summary": {"type": "string", "maxLength": 600}
            }
          }
        },
        {
          "if": {"properties": {"change_kind": {"const": "update"}}},
          "then": {
            "properties": {
              "before_resource_ref": {"$ref": "#/definitions/resource_ref"},
              "after_resource_ref": {"$ref": "#/definitions/resource_ref"},
              "before_summary": {"type": "string", "maxLength": 600},
              "after_summary": {"type": "string", "maxLength": 600}
            }
          }
        },
        {
          "if": {"properties": {"change_kind": {"const": "delete"}}},
          "then": {
            "properties": {
              "before_resource_ref": {"$ref": "#/definitions/resource_ref"},
              "after_resource_ref": {"type": "null"},
              "before_summary": {"type": "string", "maxLength": 600},
              "after_summary": {"type": "null"}
            }
          }
        }
      ]
    }
  },
  "properties": {
    "workspace_lineage_id": {"type": "string", "pattern": "^workspace_lineage:[a-f0-9]{32}$"},
    "workspace_revision_id": {"type": "string", "pattern": "^workspace_revision:[a-f0-9]{32}$"},
    "workspace_revision_ref": {"$ref": "#/definitions/ref"},
    "run_ref": {"$ref": "#/definitions/ref"},
    "task_ref": {"$ref": "#/definitions/ref"},
    "net_instance_ref": {"$ref": "#/definitions/ref"},
    "parent_revision_ref": {"$ref": "#/definitions/nullable_ref"},
    "base_revision_ref": {"$ref": "#/definitions/nullable_ref"},
    "producer_invocation_ref": {"$ref": "#/definitions/nullable_ref"},
    "transition_firing_ref": {"$ref": "#/definitions/nullable_ref"},
    "firing_workspace_binding_ref": {"$ref": "#/definitions/nullable_ref"},
    "reopen_authorization_ref": {"$ref": "#/definitions/nullable_ref"},
    "disposition": {"enum": ["genesis", "committed", "merged", "owner_reopen", "conflict"]},
    "changed_paths": {"$ref": "#/definitions/path_list"},
    "deleted_paths": {"$ref": "#/definitions/path_list"},
    "path_deltas": {
      "type": "array",
      "uniqueItems": true,
      "items": {"$ref": "#/definitions/path_delta"}
    },
    "inventory_paths": {"$ref": "#/definitions/path_list"},
    "conflict_paths": {"$ref": "#/definitions/path_list"},
    "semantic_output_refs": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/resource_ref"}},
    "trace_summary_refs": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/resource_ref"}},
    "payload_kind": {"enum": ["full_workspace_tar", "conflict_evidence"]},
    "settled": {"type": "boolean"}
  },
  "required": [
    "workspace_lineage_id", "workspace_revision_id", "workspace_revision_ref",
    "run_ref", "task_ref", "net_instance_ref", "parent_revision_ref",
    "base_revision_ref", "producer_invocation_ref", "transition_firing_ref",
    "firing_workspace_binding_ref", "disposition", "changed_paths",
    "deleted_paths", "path_deltas", "inventory_paths", "conflict_paths",
    "semantic_output_refs", "trace_summary_refs", "payload_kind", "settled"
  ],
  "allOf": [
    {
      "if": {"properties": {"disposition": {"const": "genesis"}}},
      "then": {
        "properties": {
          "parent_revision_ref": {"type": "null"},
          "base_revision_ref": {"type": "null"},
          "producer_invocation_ref": {"type": "null"},
          "transition_firing_ref": {"type": "null"},
          "firing_workspace_binding_ref": {"type": "null"},
          "path_deltas": {"maxItems": 0, "default": []},
          "payload_kind": {"const": "full_workspace_tar"},
          "settled": {"const": true}
        }
      }
    },
    {
      "if": {"properties": {"disposition": {"const": "conflict"}}},
      "then": {
        "properties": {
          "conflict_paths": {"minItems": 1},
          "path_deltas": {"maxItems": 0},
          "payload_kind": {"const": "conflict_evidence"},
          "settled": {"const": false}
        }
      },
      "else": {
        "properties": {
          "conflict_paths": {"maxItems": 0},
          "payload_kind": {"const": "full_workspace_tar"},
          "settled": {"const": true}
        }
      }
    },
    {
      "if": {"properties": {"disposition": {"const": "owner_reopen"}}},
      "then": {
        "required": ["reopen_authorization_ref"],
        "properties": {
          "parent_revision_ref": {"$ref": "#/definitions/ref"},
          "base_revision_ref": {"$ref": "#/definitions/ref"},
          "producer_invocation_ref": {"type": "null"},
          "transition_firing_ref": {"type": "null"},
          "firing_workspace_binding_ref": {"type": "null"},
          "reopen_authorization_ref": {"$ref": "#/definitions/ref"},
          "payload_kind": {"const": "full_workspace_tar"},
          "settled": {"const": true}
        }
      }
    }
  ]
}

rpnh/executable_net/v1.source:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rpnh/executable_net/v1",
  "title": "Compiled RPNH publication inventory (not an authoring schema)",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "source",
    "fragments",
    "symbolic",
    "registrations",
    "operation_handles",
    "port_handles",
    "place_aliases",
    "ports"
  ],
  "properties": {
    "schema_version": {
      "const": "rpnh/executable_net/v1"
    },
    "source": {
      "$ref": "#/definitions/module"
    },
    "fragments": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/fragment"
      }
    },
    "symbolic": {
      "$ref": "#/definitions/net"
    },
    "registrations": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": {
          "type": "object"
        }
      }
    },
    "operation_handles": {
      "$ref": "#/definitions/handles"
    },
    "port_handles": {
      "$ref": "#/definitions/handles"
    },
    "place_aliases": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/symbol"
      }
    },
    "ports": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/compiled_port"
      }
    }
  },
  "definitions": {
    "symbol": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9_-]*(?:\\.[A-Za-z][A-Za-z0-9_-]*)?$"
    },
    "key": {
      "type": "string",
      "minLength": 1
    },
    "symbols": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/definitions/symbol"
      }
    },
    "keys": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/definitions/key"
      }
    },
    "schema_id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*(?:/[a-z][a-z0-9_]*)+/v[1-9][0-9]*$"
    },
    "handles": {
      "type": "object",
      "additionalProperties": {
        "type": "string",
        "pattern": "^[a-z][a-z0-9_]{0,63}$"
      }
    },
    "place": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "schema",
        "channel",
        "capacity",
        "token_kind",
        "schema_variants",
        "colours",
        "initial_tokens",
        "reusable"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "schema": {
          "$ref": "#/definitions/schema_id"
        },
        "channel": {
          "enum": [
            "data",
            "control"
          ]
        },
        "capacity": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 1
        },
        "token_kind": {
          "enum": [
            "data",
            "agent_resource",
            "counter",
            "decision",
            "resource_lease"
          ]
        },
        "schema_variants": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/definitions/schema_id"
          }
        },
        "colours": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/colour"
          }
        },
        "initial_tokens": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/initial_token"
          }
        },
        "reusable": {
          "type": "boolean"
        }
      }
    },
    "port": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "direction",
        "schema",
        "channel",
        "cardinality"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "direction": {
          "enum": [
            "input",
            "output"
          ]
        },
        "schema": {
          "$ref": "#/definitions/schema_id"
        },
        "channel": {
          "enum": [
            "data",
            "control"
          ]
        },
        "cardinality": {
          "type": "integer",
          "minimum": 1
        },
        "cardinality_minimum": {
          "type": ["integer", "null"],
          "minimum": 0,
          "description": "Inclusive minimum; omitted or null uses cardinality."
        },
        "cardinality_maximum": {
          "type": ["integer", "null"],
          "minimum": 0,
          "description": "Inclusive maximum; omitted or null uses cardinality."
        }
      }
    },
    "compiled_port": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "direction",
        "schema",
        "channel",
        "cardinality",
        "place",
        "port_id",
        "public"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "direction": {
          "enum": [
            "input",
            "output"
          ]
        },
        "schema": {
          "$ref": "#/definitions/schema_id"
        },
        "channel": {
          "enum": [
            "data",
            "control"
          ]
        },
        "cardinality": {
          "type": "integer",
          "minimum": 1
        },
        "cardinality_minimum": {
          "type": ["integer", "null"],
          "minimum": 0,
          "description": "Inclusive minimum; omitted or null uses cardinality."
        },
        "cardinality_maximum": {
          "type": ["integer", "null"],
          "minimum": 0,
          "description": "Inclusive maximum; omitted or null uses cardinality."
        },
        "place": {
          "$ref": "#/definitions/symbol"
        },
        "port_id": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9_]{0,63}$"
        },
        "public": {
          "type": "boolean"
        }
      }
    },
    "binding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "place"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "place": {
          "$ref": "#/definitions/symbol"
        }
      }
    },
    "product": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "port",
        "minimum",
        "maximum"
      ],
      "properties": {
        "port": {
          "$ref": "#/definitions/symbol"
        },
        "minimum": {
          "type": "integer",
          "minimum": 0
        },
        "maximum": {
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "effect": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "key",
        "bindings",
        "config",
        "references"
      ],
      "properties": {
        "key": {
          "$ref": "#/definitions/key"
        },
        "bindings": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/symbol"
          }
        },
        "config": {
          "type": "object"
        },
        "references": {
          "type": "object",
          "propertyNames": {
            "type": "string",
            "pattern": "^[A-Za-z][A-Za-z0-9_-]*$"
          },
          "additionalProperties": {
            "$ref": "#/definitions/symbol_reference"
          }
        }
      }
    },
    "outcome": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "products",
        "effects"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "products": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/product"
          }
        },
        "effects": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/effect"
          }
        }
      }
    },
    "operation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "executor",
        "inputs",
        "outputs",
        "outcomes",
        "tools",
        "config",
        "request_port",
        "budget_binding"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "executor": {
          "$ref": "#/definitions/key"
        },
        "inputs": {
          "$ref": "#/definitions/symbols"
        },
        "outputs": {
          "$ref": "#/definitions/symbols"
        },
        "outcomes": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/definitions/outcome"
          }
        },
        "tools": {
          "$ref": "#/definitions/keys"
        },
        "config": {
          "type": "object"
        },
        "request_port": {
          "anyOf": [
            {
              "$ref": "#/definitions/symbol"
            },
            {
              "type": "null"
            }
          ]
        },
        "budget_binding": {
          "anyOf": [
            {
              "$ref": "#/definitions/operationBudgetBinding"
            },
            {
              "type": "null"
            }
          ]
        }
      }
    },
    "transition": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "operation",
        "count_guards",
        "input_verdicts"
      ],
      "properties": {
        "name": {
          "$ref": "#/definitions/symbol"
        },
        "operation": {
          "$ref": "#/definitions/symbol"
        },
        "count_guards": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/count_guard"
          }
        },
        "input_verdicts": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/input_verdict"
          }
        }
      }
    },
    "arc": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "place",
        "transition",
        "direction",
        "weight",
        "mode",
        "outcome",
        "emit",
        "forward_source",
        "colour_expression",
        "output_predicates",
        "lease_claims",
        "lease_claim_exclusions",
        "lease_claim_set",
        "effect_selector"
      ],
      "properties": {
        "place": {
          "$ref": "#/definitions/symbol"
        },
        "transition": {
          "$ref": "#/definitions/symbol"
        },
        "direction": {
          "enum": [
            "input",
            "output"
          ]
        },
        "weight": {
          "type": "integer",
          "minimum": 1
        },
        "mode": {
          "enum": [
            "consume",
            "read",
            "borrow",
            "guard",
            "produce",
            "return"
          ]
        },
        "outcome": {
          "anyOf": [
            {
              "$ref": "#/definitions/symbol"
            },
            {
              "type": "null"
            }
          ]
        },
        "emit": {
          "enum": [
            "produced",
            "content_less",
            "forward",
            "control_only",
            "route_selected",
            "lease_mint"
          ]
        },
        "forward_source": {
          "anyOf": [
            {
              "$ref": "#/definitions/symbol"
            },
            {
              "type": "null"
            }
          ]
        },
        "colour_expression": {
          "anyOf": [
            {
              "$ref": "#/definitions/colour_expression"
            },
            {
              "type": "null"
            }
          ]
        },
        "output_predicates": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/input_verdict"
          }
        },
        "lease_claims": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/lease_claim_expression"
          }
        },
        "lease_claim_exclusions": {
          "$ref": "#/definitions/symbols"
        },
        "lease_claim_set": {
          "anyOf": [
            {
              "$ref": "#/definitions/lease_claim_set_expression"
            },
            {
              "type": "null"
            }
          ]
        },
        "effect_selector": {
          "anyOf": [
            {
              "$ref": "#/definitions/symbol"
            },
            {
              "type": "null"
            }
          ]
        }
      }
    },
    "reset_arc": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "place",
        "transition",
        "selector",
        "outcome"
      ],
      "properties": {
        "place": {
          "$ref": "#/definitions/symbol"
        },
        "transition": {
          "$ref": "#/definitions/symbol"
        },
        "selector": {
          "$ref": "#/definitions/symbol"
        },
        "outcome": {
          "anyOf": [
            {
              "$ref": "#/definitions/symbol"
            },
            {
              "type": "null"
            }
          ]
        }
      }
    },
    "fragment": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "places",
        "transitions",
        "arcs",
        "ports",
        "operations",
        "internal_ports",
        "internal_bindings",
        "lease_identities",
        "lease_pools",
        "variable_resource_arcs",
        "logical_slots",
        "reset_arcs"
      ],
      "properties": {
        "places": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/place"
          }
        },
        "transitions": {
          "type": "array",
